*/
scwin.setReportNameInfo = function (formCd, formNm) {
    /* sdd-asis-lifecycle:begin setReportNameInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_reportNmTemp').setValue(formNm);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnValidationCheck
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnValidationCheck = async function () {
    /* sdd-asis-lifecycle:begin fnValidationCheck — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!$c.date.isDate($c.util.getComponent('cal_fromDate').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return false;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toDate').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return false;
    }
    if (!($c.date.diffDate($c.util.getComponent('cal_fromDate').getValue(), $c.util.getComponent('cal_toDate').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
        return false;
    }
    if ($c.date.addYear($c.util.getComponent('cal_fromDate').getValue(), 3) < $c.date.addYear($c.util.getComponent('cal_toDate').getValue(), 0)) {
        await $c.win.alert("조회기간은 3년 이내만 가능합니다.");
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.openFindReportName
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.openFindReportName = function () {
    /* sdd-asis-lifecycle:begin openFindReportName — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const url = "/common/reportname.do?method=loadInitPage&errTrdRlf=Y";
    $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { id: "보고서명찾기", scrollbars: true, resizable: false, width: "530", height: "650", type: "pageFramePopup" }, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    setTimeout(function() {
            $("#AKCDiv").hide();
        }, 200);
    const searchCorpName = $("#searchForm").find("input:text[name=searchCorpName]").val();
    const reportName = $c.util.getComponent('ipt_reportNmTemp').getValue().replace(/(\s*)/g, "");
    $c.util.getComponent("dma_fnDownloadReq").set("reportNm", reportName);
    if ($(document).find("select[id=ipt_currentPageSize]").val() != null) {
        $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    }
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchErrorTradeReliefSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "searchErrorTradeRelief_sub");
    await scwin.tx_fnSearch_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
